#!/usr/bin/env bash
# UPDATES: build the Sparkle appcast for a release.
#
# Usage: ./scripts/generate_appcast.sh <releases-dir>
#        ./scripts/generate_appcast.sh --fix-urls <appcast.xml>
#
#   <releases-dir> must contain versioned release DMGs only
#   (YappYapp-<version>.dmg) and, ideally, the current published appcast.xml
#   so earlier items are kept. Writes appcast.xml into the same directory,
#   EdDSA-signing each new archive with the key generated by Sparkle's
#   generate_keys (login keychain locally, or SPARKLE_PRIVATE_KEY_FILE in CI).
#
# The appcast is served from the repo root on main:
#   https://raw.githubusercontent.com/migueltorrezd/yappyapp-releases/main/appcast.xml
# so a release = upload DMG to GitHub Releases + commit the regenerated
# appcast.xml. See docs/RELEASE_CHECKLIST.md (Publishing a release).
#
# YA-76: generate_appcast applies one --download-url-prefix to every item it
# writes, which pointed older DMGs at the new tag. After generation every
# enclosure URL is rewritten from its own file name, so YappYapp-0.3.1.dmg
# always resolves to releases/download/v0.3.1/YappYapp-0.3.1.dmg.
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DOWNLOAD_BASE="https://github.com/migueltorrezd/yappyapp-releases/releases/download"

# Rewrites every enclosure URL in an appcast to the per-version release asset.
fix_enclosure_urls() {
  local appcast="$1"
  DOWNLOAD_BASE="$DOWNLOAD_BASE" ruby - "$appcast" <<'RUBY'
path = ARGV.fetch(0)
base = ENV.fetch("DOWNLOAD_BASE")
xml = File.read(path)
bad = []
fixed = xml.gsub(/(<enclosure\b[^>]*\burl=")([^"]*)(")/) do
  head, url, tail = Regexp.last_match(1), Regexp.last_match(2), Regexp.last_match(3)
  name = url.split("/").last.to_s
  match = name.match(/\AYappYapp-(\d+(?:\.\d+)*)\.dmg\z/)
  if match
    "#{head}#{base}/v#{match[1]}/#{name}#{tail}"
  else
    bad << url
    "#{head}#{url}#{tail}"
  end
end
unless bad.empty?
  warn "error: appcast enclosures without a versioned YappYapp-<version>.dmg name:"
  bad.each { |url| warn "  - #{url}" }
  exit 1
end
File.write(path, fixed)
RUBY
}

if [[ "${1:-}" == "--fix-urls" ]]; then
  fix_enclosure_urls "${2:?usage: generate_appcast.sh --fix-urls <appcast.xml>}"
  exit 0
fi

RELEASES_DIR="${1:?usage: generate_appcast.sh <releases-dir>}"

GENERATE_APPCAST="$ROOT_DIR/.build/artifacts/sparkle/Sparkle/bin/generate_appcast"
if [[ ! -x "$GENERATE_APPCAST" ]]; then
  echo "error: generate_appcast not found; run 'swift build' to fetch the Sparkle artifact" >&2
  exit 1
fi

# The evergreen YappYapp.dmg is a byte copy of the versioned DMG; feeding both
# to generate_appcast creates a duplicate item for the same build.
shopt -s nullglob
for archive in "$RELEASES_DIR"/*.dmg "$RELEASES_DIR"/*.zip; do
  if [[ ! "$(basename "$archive")" =~ ^YappYapp-[0-9]+(\.[0-9]+)*\.dmg$ ]]; then
    echo "error: $archive is not a versioned YappYapp-<version>.dmg; keep only versioned DMGs in $RELEASES_DIR" >&2
    exit 1
  fi
done
shopt -u nullglob

VERSION="$(plutil -extract app.short_version raw -o - "$ROOT_DIR/docs/RELEASE_PROVENANCE.json")"
if [[ ! -f "$RELEASES_DIR/YappYapp-$VERSION.dmg" ]]; then
  echo "error: $RELEASES_DIR/YappYapp-$VERSION.dmg is missing (version from docs/RELEASE_PROVENANCE.json)" >&2
  exit 1
fi
DOWNLOAD_PREFIX="$DOWNLOAD_BASE/v${VERSION}/"

# No deltas: only the DMGs are uploaded to GitHub Releases.
ARGS=(--download-url-prefix "$DOWNLOAD_PREFIX" --maximum-deltas 0 -o "$RELEASES_DIR/appcast.xml")
# CI has no login keychain; it supplies the exported key file instead.
if [[ -n "${SPARKLE_PRIVATE_KEY_FILE:-}" ]]; then
  ARGS+=(--ed-key-file "$SPARKLE_PRIVATE_KEY_FILE")
fi

"$GENERATE_APPCAST" "${ARGS[@]}" "$RELEASES_DIR"
fix_enclosure_urls "$RELEASES_DIR/appcast.xml"
echo "Wrote $RELEASES_DIR/appcast.xml (each enclosure points at its own v<version> release asset)"
